/bin/bash -c "python3 - <<'PY'
from pathlib import Path
import re, statistics
text=Path('tmp/pdfs/page-13.txt').read_text()
rows=[]
for line in text.splitlines():
    m=re.match(r'"'^'"\\s*([a-z ]+?)\\s{2,}(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)',line)
    if m: rows.append((m.group(1).strip(), *map(float,m.groups()[1:])))
print('Occupational rows:',len(rows))
for name,group in [('all',rows),('male-stereotyped',rows[:20]),('female-stereotyped',rows[20:])]:
    print(name, {'single STS':statistics.mean(r[1] for r in group), 'single feminine %':statistics.mean(r[2] for r in group), 'paired STS':statistics.mean(r[3] for r in group), 'paired feminine %':statistics.mean(r[4] for r in group), 'mean absolute single STS':statistics.mean(abs(r[1]) for r in group)})
rows2=[]
for line in Path('tmp/pdfs/page-15.txt').read_text().splitlines():
    m=re.match(r'"'^'"\\s*([a-z ]+?)\\s{2,}(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)',line)
    if m: rows2.append((m.group(1).strip(),*map(float,m.groups()[1:])))
print('Power rows:',len(rows2))
for name,group in [('all',rows2),('powerless',[r for r in rows2 if r[0].endswith('minor')]),('powerful',[r for r in rows2 if r[0].endswith('power')])]:
    print(name, {'single STS':statistics.mean(r[1] for r in group), 'paired STS':statistics.mean(r[2] for r in group)})
PY"
